-- One row is the complete runtime metadata for one service resource.

create table if not exists public.service_resource_metadata (
  id bigint generated by default as identity primary key,
  service_name text not null,
  resource_name text not null,
  table_name text not null,
  version integer not null default 1 check (version > 0),
  config jsonb not null,
  enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint service_resource_metadata_service_resource_key unique (service_name, resource_name),
  constraint service_resource_metadata_service_name_check check (service_name ~ '^[A-Za-z][A-Za-z0-9]*$'),
  constraint service_resource_metadata_resource_name_check check (resource_name ~ '^[A-Za-z_][A-Za-z0-9_]*$'),
  constraint service_resource_metadata_table_name_check check (table_name ~ '^[A-Za-z_][A-Za-z0-9_.]*$'),
  constraint service_resource_metadata_config_object_check check (jsonb_typeof(config) = 'object'),
  constraint service_resource_metadata_table_consistency_check check (config ->> 'tableName' = table_name)
);

comment on table public.service_resource_metadata is
  'Database-owned runtime metadata for BaseService CRUD resources; one row per service resource.';
comment on column public.service_resource_metadata.config is
  'Complete ResourceConfig JSON consumed asynchronously by BaseService.';

create index if not exists service_resource_metadata_service_enabled_idx
  on public.service_resource_metadata (service_name, enabled, resource_name);

alter table public.service_resource_metadata enable row level security;
revoke all on table public.service_resource_metadata from anon, authenticated;
grant select on table public.service_resource_metadata to service_role;

